css:
.urb-sim-container {
    padding: 24px;
    background: #f3f4f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.urb-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e5d 100%);
    color: #ffffff;
    padding: 28px 32px;
    border-radius: 6px;
    border-left: 6px solid #d4a017;
    margin-bottom: 22px;
    box-shadow: 0 4px 14px rgba(26, 39, 68, 0.18);
}
.urb-header-tag {
    font-size: 0.72rem;
    letter-spacing: 0.18em;
    color: #d4a017;
    text-transform: uppercase;
    margin-bottom: 8px;
    font-weight: 600;
}
.urb-header h1 {
    margin: 0;
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: #ffffff;
}
.urb-header-sub {
    margin-top: 6px;
    color: #cbd2dc;
    font-size: 0.95rem;
    font-style: italic;
}

.urb-status-bar {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.urb-status-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 14px 18px;
}
.urb-status-card.urb-status-rate {
    border-top-color: #c0392b;
}
.urb-status-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #5c6a80;
    margin-bottom: 8px;
    font-weight: 600;
}
.urb-status-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.urb-status-value.urb-rate { color: #c0392b; }
.urb-status-value.urb-score { color: #2d6a4f; }

.urb-round-panel {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 6px;
    padding: 28px 28px 24px 28px;
    margin-bottom: 22px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    position: relative;
}
.urb-round-tag {
    position: absolute;
    top: 0;
    right: 24px;
    background: #d4a017;
    color: #1a2744;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    padding: 4px 12px;
    border-radius: 0 0 4px 4px;
}
.urb-round-panel h2 {
    margin: 0 0 8px 0;
    color: #1a2744;
    font-size: 1.3rem;
    font-weight: 700;
    border-bottom: 2px solid #d4a017;
    padding-bottom: 8px;
    display: inline-block;
}
.urb-round-intro {
    color: #4a5468;
    line-height: 1.55;
    margin-bottom: 22px;
    font-size: 0.95rem;
    max-width: 820px;
}

.urb-workers-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(290px, 1fr));
    gap: 16px;
}
.urb-worker-card {
    background: #f8f9fb;
    border: 1px solid #d8dde6;
    border-left: 4px solid #4361ee;
    border-radius: 4px;
    padding: 16px;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.urb-worker-card:hover {
    border-left-color: #d4a017;
    box-shadow: 0 4px 12px rgba(26, 39, 68, 0.08);
}
.urb-worker-head {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}
.urb-worker-num {
    width: 30px;
    height: 30px;
    background: #1a2744;
    color: #d4a017;
    font-weight: 700;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    flex-shrink: 0;
}
.urb-worker-name {
    font-weight: 700;
    color: #1a2744;
    font-size: 1rem;
}
.urb-worker-desc {
    font-size: 0.85rem;
    line-height: 1.5;
    color: #3a4660;
    margin-bottom: 14px;
    min-height: 60px;
}

.urb-sim-container select,
.urb-sim-container input[type="number"] {
    width: 100%;
    padding: 8px 10px;
    background: #ffffff;
    border: 1px solid #c5cdd9;
    color: #1a2744;
    border-radius: 4px;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.urb-sim-container select option {
    background: #ffffff;
    color: #1a2744;
}
.urb-sim-container input[type="number"]:focus,
.urb-sim-container select:focus {
    outline: none;
    border-color: #d4a017;
    box-shadow: 0 0 0 3px rgba(212, 160, 23, 0.18);
}

.urb-decomp {
    background: #f8f9fb;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 18px 20px;
    margin-bottom: 24px;
}
.urb-decomp-row {
    display: grid;
    grid-template-columns: 130px 1fr 60px;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
}
.urb-decomp-tag {
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 5px 8px;
    border-radius: 3px;
    text-align: center;
}
.urb-tag-fric { background: #e3f2fd; color: #135ea6; }
.urb-tag-struc { background: #fce4ec; color: #c2185b; }
.urb-tag-cycl { background: #fff8e1; color: #8a6508; }
.urb-decomp-bar {
    height: 16px;
    background: #ecedf2;
    border-radius: 8px;
    overflow: hidden;
}
.urb-decomp-fill {
    height: 100%;
    border-radius: 8px;
}
.urb-fill-fric { background: linear-gradient(90deg, #4fa1e0, #1976d2); }
.urb-fill-struc { background: linear-gradient(90deg, #e57b9c, #c2185b); }
.urb-fill-cycl { background: linear-gradient(90deg, #f3c759, #d4a017); }
.urb-decomp-num {
    font-weight: 700;
    color: #1a2744;
    text-align: right;
    font-size: 1rem;
}
.urb-decomp-total {
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px dashed #c5cdd9;
    font-size: 1.05rem;
    color: #1a2744;
}
.urb-decomp-total strong {
    color: #c0392b;
    font-size: 1.2rem;
}

.urb-framing-h {
    margin: 18px 0 10px 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
}
.urb-framing-select {
    width: 100%;
    max-width: 740px;
}

.urb-budget-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px;
    margin-bottom: 18px;
}
.urb-lever {
    background: #f8f9fb;
    border: 1px solid #d8dde6;
    border-top: 4px solid #4361ee;
    border-radius: 4px;
    padding: 14px 16px;
    display: flex;
    flex-direction: column;
}
.urb-lever-l1 { border-top-color: #1976d2; }
.urb-lever-l2 { border-top-color: #c2185b; }
.urb-lever-l3 { border-top-color: #d4a017; }
.urb-lever-l4 { border-top-color: #2d6a4f; }
.urb-lever-l5 { border-top-color: #6b7a90; }
.urb-lever-target {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: #5c6a80;
    margin-bottom: 6px;
}
.urb-lever-l1 .urb-lever-target { color: #135ea6; }
.urb-lever-l2 .urb-lever-target { color: #c2185b; }
.urb-lever-l3 .urb-lever-target { color: #8a6508; }
.urb-lever-l4 .urb-lever-target { color: #2d6a4f; }
.urb-lever-l5 .urb-lever-target { color: #5c6a80; }
.urb-lever-label {
    font-weight: 700;
    color: #1a2744;
    font-size: 0.95rem;
    margin-bottom: 6px;
    line-height: 1.3;
}
.urb-lever-hint {
    color: #4a5468;
    font-size: 0.78rem;
    line-height: 1.45;
    margin-bottom: 14px;
    flex-grow: 1;
}
.urb-lever-input {
    display: flex;
    align-items: stretch;
    gap: 0;
    border-radius: 4px;
    overflow: hidden;
}
.urb-lever-input input {
    flex: 1;
    text-align: right;
    font-weight: 700;
    border-radius: 0;
    border-left: none;
    border-right: none;
    font-size: 1rem;
}
.urb-currency {
    background: #1a2744;
    color: #ffffff;
    font-weight: 700;
    padding: 8px 12px;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    border-radius: 4px 0 0 4px;
}
.urb-millions {
    background: #1a2744;
    color: #ffffff;
    font-weight: 700;
    padding: 8px 12px;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    border-radius: 0 4px 4px 0;
}

.urb-budget-totalrow {
    background: #1a2744;
    color: #ffffff;
    padding: 14px 18px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 1.05rem;
    text-align: center;
    letter-spacing: 0.04em;
}
.urb-budget-ok { color: #4ade80; }
.urb-budget-bad { color: #fca5a5; }

.urb-controls {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 6px;
    padding: 16px 20px;
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 22px;
    flex-wrap: wrap;
}
.urb-submit {
    background: #1a2744;
    border: none;
    color: #ffffff;
    font-weight: 700;
    padding: 11px 26px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    border-radius: 4px;
    transition: all 0.2s ease;
    font-size: 0.85rem;
}
.urb-submit:hover {
    background: #d4a017;
    color: #1a2744;
}
.urb-undo {
    border: 1px solid #c5cdd9;
    background: #ffffff;
    color: #4a5468;
    font-weight: 600;
}
.urb-controls-spacer { flex: 1; }
.urb-framing-display {
    color: #4a5468;
    font-size: 0.9rem;
}
.urb-framing-display strong {
    color: #1a2744;
    background: #fff8e1;
    padding: 3px 9px;
    border-radius: 3px;
    border: 1px solid #d4a017;
}

.urb-section-h {
    color: #1a2744;
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 12px 0;
}

.urb-history-wrap {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 6px;
    padding: 18px 20px;
    margin-bottom: 22px;
    overflow-x: auto;
}
.urb-history {
    margin: 0;
    width: 100%;
}
.urb-history th {
    background: #1a2744;
    color: #ffffff !important;
    font-weight: 700;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 10px 12px;
    border: none;
}
.urb-history td {
    color: #1a2744;
    padding: 10px 12px;
    border-color: #ecedf2;
    font-size: 0.9rem;
}
.urb-history tbody tr:hover {
    background: #f8f9fb;
}

.urb-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 16px;
    margin-bottom: 22px;
}
.urb-chart-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 6px;
    padding: 16px;
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .urb-sim-container { padding: 12px; }
    .urb-header { padding: 22px; }
    .urb-header h1 { font-size: 1.4rem; }
    .urb-status-bar { grid-template-columns: 1fr 1fr; }
    .urb-decomp-row { grid-template-columns: 100px 1fr 50px; }
    .urb-controls { flex-direction: column; align-items: stretch; }
    .urb-controls-spacer { display: none; }
    .urb-round-tag { right: 12px; font-size: 0.65rem; }
}


/* --- EQIL 2026-08-07: accessibility, focus, motion, completion panel --- */
.urb-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
}
.urb-worker-role {
    font-size: 0.78rem;
    color: #5c6a80;
}
.urb-sim-container :focus-visible,
.urb-sim-container select:focus-visible,
.urb-sim-container input:focus-visible,
.urb-sim-container button:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
    border-radius: 3px;
}
.urb-completion {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-left: 6px solid #2d6a4f;
    border-radius: 6px;
    padding: 22px 26px;
    margin: 22px 0;
    color: #1a2744;
}
.urb-debrief h3 {
    margin: 0 0 10px;
    font-size: 1.15rem;
    color: #1a2744;
}
.urb-debrief-headline {
    font-size: 1rem;
    margin-bottom: 14px;
}
.urb-debrief-list {
    list-style: none;
    padding: 0;
    margin: 0 0 14px;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 8px;
}
.urb-debrief-list li {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    background: #f8f9fb;
    border: 1px solid #e2e6ee;
    border-radius: 4px;
    padding: 8px 12px;
}
.urb-debrief-k { color: #5c6a80; font-size: 0.82rem; }
.urb-debrief-v { font-weight: 700; }
.urb-debrief-insights p {
    margin: 0 0 8px;
    font-size: 0.9rem;
    line-height: 1.5;
}
@media (prefers-reduced-motion: reduce) {
    .urb-sim-container *,
    .urb-sim-container *::before,
    .urb-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "1212";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        // 1.3: only the texts decide. Numeric values alone (0, 1, 2) no longer keep a decision in order: many
        // decisions with named options use them, and a fixed order there let the first or last option win.
        var nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
