            }

            if (period === 3) {
                const blank = ['l1Input', 'l2Input', 'l3Input', 'l4Input', 'l5Input'].some(function(id) {
                    const el = document.getElementById(id);
                    return !el || String(el.value).trim() === '' || isNaN(parseFloat(el.value));
