        calculateResults(state) {
            const period = state.currentPeriod;
            const results = { period: period };

            if (period === 1) {
                let correct = 0;
                const detail = [];
                for (let i = 0; i < this.WORKERS.length; i++) {
                    const w = this.WORKERS[i];
                    const chosen = state.decisions.classifications['w' + (i + 1)];
                    const isCorrect = (chosen === w.correct);
                    if (isCorrect) correct++;
                    detail.push({ name: w.name, chosen: chosen, expected: w.correct, ok: isCorrect });
                }
                state.domainState.correctCount = correct;
                state.domainState.classifications = state.decisions.classifications;
                const score = Math.round((correct / 8) * 100);
                state.domainState.score = score;
                state.domainState.scoreHistory.push(score);
                state.domainState.rateHistory.push(8);
                results.classificationDetail = detail;
                results.correctCount = correct;
                results.score = score;
                results.summary = correct + ' / 8';
                results.rate = 8;
            } else if (period === 2) {
                const choice = state.decisions.framing;
                state.domainState.framingChoice = choice;
                let framingScore = 0;
                if (choice === 'F1') framingScore = 35;
                else if (choice === 'F2') framingScore = 50;
                else if (choice === 'F3') framingScore = 95;
                state.domainState.framingScore = framingScore;
                state.domainState.score = framingScore;
                state.domainState.scoreHistory.push(framingScore);
                state.domainState.rateHistory.push(8);
                results.framingChoice = choice;
                results.score = framingScore;
                results.summary = choice;
                results.rate = 8;
            } else if (period === 3) {
                const d = state.decisions;

                const fricReduction = Math.min(2.5, 1.8 * (d.l1 / 5));
                const strucReduction = Math.min(1.65, 0.7 * (d.l2 / 15) + 0.85 * (d.l4 / 7));
                const cyclReduction = Math.min(2.6, 1.7 * (d.l3 / 20));
                const longTermBoost = Math.min(0.4, 0.3 * (d.l5 / 3));

                const fricFinal = Math.max(1.0, 3 - fricReduction);
                const strucFinal = Math.max(0.4, 2 - strucReduction);
                const cyclFinal = Math.max(0.4, 3 - cyclReduction);
                const finalRate = Math.round(Math.max(2, fricFinal + strucFinal + cyclFinal - longTermBoost) * 10) / 10;

                const helped = {
                    Camila: d.l1 >= 3,
                    Roberto: d.l2 >= 8,
                    Gabriela: d.l3 >= 10,
                    Diego: d.l1 >= 3,
                    Yolanda: d.l4 >= 5,
                    Luis: d.l3 >= 8 || d.l5 >= 2,
                    Andrea: d.l5 >= 2,
                    Marco: d.l4 >= 5
                };
                let helpedCount = 0;
                Object.keys(helped).forEach(function(k) { if (helped[k]) helpedCount++; });

                state.domainState.finalRate = finalRate;
                state.domainState.workersHelped = helpedCount;
                state.domainState.yolandaHelped = helped.Yolanda;
                state.domainState.marcoHelped = helped.Marco;

                let coverageScore = (helpedCount / 8) * 60;
                let rateScore = Math.max(0, (8 - finalRate) / 6) * 40;
                let policyScore = Math.round(Math.min(100, coverageScore + rateScore));

                state.domainState.score = policyScore;
                state.domainState.scoreHistory.push(policyScore);
                state.domainState.rateHistory.push(finalRate);

                results.l1 = d.l1; results.l2 = d.l2; results.l3 = d.l3; results.l4 = d.l4; results.l5 = d.l5;
                results.finalRate = finalRate;
                results.rate = finalRate;
                results.workersHelped = helpedCount;
                results.yolandaHelped = helped.Yolanda;
                results.marcoHelped = helped.Marco;
                results.score = policyScore;
                results.helpedDetail = helped;
                results.summary = helpedCount + ' / 8 helped';
            }

            /* platform score: running mean of the round scores, the same average getPerformanceSummary reports, native 0 to 100 */
            const runHist = state.domainState.scoreHistory || [];
            const runSum = runHist.reduce(function(a, b) { return a + (Number(b) || 0); }, 0);
            const runScore = runHist.length ? Math.max(0, Math.min(100, Math.round(runSum / runHist.length))) : 0;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: runScore });

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: state.domainState, decisions: {} });
            }, 400);

            return results;
        }

