            if (r2) r2.style.display = (period === 2) ? 'block' : 'none';
            if (r3) r3.style.display = (period === 3) ? 'block' : 'none';

            const controls = document.getElementById('urbControls');
            if (controls) controls.style.display = over ? 'none' : 'flex';
