                if (container && (container.children.length === 0 || this._renderedLang !== lang)) {
                    const keep = {};
                    for (let k = 1; k <= 8; k++) {
                        const prev = document.getElementById('worker' + k + 'Select');
                        if (prev && prev.value) keep['w' + k] = prev.value;
                    }
                    this._renderedLang = lang;
                    let html = '';
                    for (let i = 0; i < this.WORKERS.length; i++) {
                        const w = this.WORKERS[i];
                        const role = (lang === 'es') ? w.role_es : w.role_en;
                        const desc = (lang === 'es') ? w.desc_es : w.desc_en;
                        html += '<div class="urb-worker-card">';
                        html += '<div class="urb-worker-head">';
                        html += '<span class="urb-worker-num">' + (i + 1) + '</span>';
                        html += '<div><div class="urb-worker-name">' + w.name + ', ' + w.age + '</div>';
                        html += '<div class="urb-worker-role" id="workerRole' + (i + 1) + '">' + role + '</div></div>';
                        html += '</div>';
                        html += '<div class="urb-worker-desc" id="workerDesc' + (i + 1) + '">' + desc + '</div>';
                        html += '<label class="urb-visually-hidden" for="worker' + (i + 1) + 'Select">' +
                                this._t('classify_label') + ' ' + w.name + '</label>';
                        html += '<select id="worker' + (i + 1) + 'Select" class="urb-worker-select"' +
                                ' aria-describedby="workerDesc' + (i + 1) + '">';
                        html += '<option value="" data-i18n="opt_choose">— choose —</option>';
                        html += '<option value="frictional" data-i18n="opt_frictional">Frictional</option>';
                        html += '<option value="structural" data-i18n="opt_structural">Structural</option>';
                        html += '<option value="cyclical" data-i18n="opt_cyclical">Cyclical</option>';
                        html += '<option value="seasonal" data-i18n="opt_seasonal">Seasonal</option>';
                        html += '<option value="underemployed" data-i18n="opt_under">Underemployed</option>';
                        html += '<option value="discouraged" data-i18n="opt_discouraged">Discouraged worker</option>';
                        html += '</select>';
                        html += '</div>';
                    }
                    container.innerHTML = html;
                    Object.keys(keep).forEach(function(k) {
                        const el = document.getElementById('worker' + k.substring(1) + 'Select');
                        if (el) el.value = keep[k];
                    });
                    if (window.mySimulation && window.mySimulation.translationManager && window.mySimulation.translationManager.applyTranslations) {
                        window.mySimulation.translationManager.applyTranslations();
                    }
                }
            }

            if (period === 3) {
                const updateTotal = function() {
                    const l1 = parseFloat((document.getElementById('l1Input') || {}).value) || 0;
                    const l2 = parseFloat((document.getElementById('l2Input') || {}).value) || 0;
                    const l3 = parseFloat((document.getElementById('l3Input') || {}).value) || 0;
                    const l4 = parseFloat((document.getElementById('l4Input') || {}).value) || 0;
                    const l5 = parseFloat((document.getElementById('l5Input') || {}).value) || 0;
                    const sum = l1 + l2 + l3 + l4 + l5;
                    const totalEl = document.getElementById('budgetTotal');
                    if (totalEl) {
                        totalEl.textContent = 'CO$' + sum.toFixed(1) + 'M / CO$50M';
                        totalEl.className = (Math.abs(sum - 50) < 0.01) ? 'urb-budget-ok' : 'urb-budget-bad';
                    }
                };
                ['l1Input', 'l2Input', 'l3Input', 'l4Input', 'l5Input'].forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el && !el.dataset.bound) {
                        el.addEventListener('input', updateTotal);
                        el.dataset.bound = '1';
                    }
                });
                updateTotal();
            }
        }

        _syncControlsFromDecisions(state) {
            const dec = (state && state.decisions) || {};
            const cls = dec.classifications || (state && state.domainState && state.domainState.classifications) || {};
            Object.keys(cls).forEach(function(k) {
                const el = document.getElementById('worker' + k.substring(1) + 'Select');
                if (el && cls[k]) el.value = cls[k];
            });
            const fr = dec.framing || (state && state.domainState && state.domainState.framingChoice);
            const frEl = document.getElementById('framingSelect');
            if (frEl && fr) frEl.value = fr;
            ['l1', 'l2', 'l3', 'l4', 'l5'].forEach(function(k) {
                const el = document.getElementById(k + 'Input');
                if (el && typeof dec[k] === 'number') el.value = String(dec[k]);
            });
        }

